// Extract AI agent output
const items = $input.all();

for (const item of items) {
  // Default values
  item.json.hasErrors = false;
  item.json.errorDetails = [];

  // Get the output text
  const output = item.json.output || item.json.text || '';

  // Check for explicit failure message
  if (output.includes('I_HAVE_FAILED')) {
    item.json.hasErrors = true;
    item.json.errorDetails.push('AI explicitly indicated failure with I_HAVE_FAILED marker');
  }

  // Basic validation checks
  if (!output.includes('Candidate Evaluation:')) {
    item.json.hasErrors = true;
    item.json.errorDetails.push('Missing expected section: Candidate Evaluation');
  }

  if (!output.includes('Matching Score:')) {
    item.json.hasErrors = true;
    item.json.errorDetails.push('Missing expected section: Matching Score');
  }

  if (!output.includes('Recommendation:')) {
    item.json.hasErrors = true;
    item.json.errorDetails.push('Missing expected section: Recommendation');
  }

  // Check for empty analysis
  if (output.length < 500) {
    item.json.hasErrors = true;
    item.json.errorDetails.push('Output suspiciously short, likely incomplete analysis');
  }

  // Log error status
  console.log(`Error check complete. hasErrors: ${item.json.hasErrors}`, 
              item.json.errorDetails);
}

// Return all items, including error flags
return items;

